import{c as a,$ as o,Q as n,j as i,g as t,o as s,n as l,m as c}from"./chunks/framework.Ce_49mA8.js";const b=JSON.parse('{"title":"Service Orders","description":"Practical guide to managing workshop service orders in OmniCraft ERP — repair stage tracking, customer deposits, spare parts deduction, and cash register integration.","frontmatter":{"title":"Service Orders","description":"Practical guide to managing workshop service orders in OmniCraft ERP — repair stage tracking, customer deposits, spare parts deduction, and cash register integration.","datePublished":"2026-11-15","dateModified":"2026-11-25","order":12},"headers":[],"relativePath":"docs/spaces/services/orders.md","filePath":"docs/spaces/services/orders.md","lastUpdated":1795564800000}'),d={name:"docs/spaces/services/orders.md"},u={id:"service-orders-work-orders-desk-execution-stages",tabindex:"-1"};function p(h,e,m,g,f,v){const r=o("DocIcon");return n(),i("div",null,[t("h1",u,[s(r,{name:"terms"}),e[0]||(e[0]=l(" Service Orders: Work Orders Desk & Execution Stages ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#service-orders-work-orders-desk-execution-stages","aria-label":'Permalink to "Service Orders: Work Orders Desk & Execution Stages"'},"​",-1))]),e[2]||(e[2]=c('<p>In a repair and maintenance workshop, the service order desk acts as your central operational dispatcher. Unlike mass production lines where identical goods flow in uniform batches, every service ticket is distinct: each involves an individual customer, specific fault history, tailored spare parts, and dynamic delivery estimates.</p><p>When work tickets are tracked on loose sticky notes or scattered across messaging apps, workshops suffer routine organizational breakdowns: technicians lose track of paid customer deposits, hidden assembly damages surface during teardown without customer sign-off, and warehouse parts vanish without accountability.</p><p>In <strong>OmniCraft ERP</strong>, the <strong>&quot;Orders&quot;</strong> tab merges all physical repair stages and monetary flows into a single source of truth. Every work order connects the customer profile, planned service items, inventory parts, and cash entries into an unbroken operational chain.</p><hr><h2 id="anatomy-of-a-service-order-card" tabindex="-1">Anatomy of a Service Order Card <a class="header-anchor" href="#anatomy-of-a-service-order-card" aria-label="Permalink to &quot;Anatomy of a Service Order Card&quot;">​</a></h2><p>Every ticket checked into the shop appears on the dispatcher desk as a structured card displaying all vital metrics:</p><ul><li><strong>Order Identifier:</strong> A unique serial code (e.g., <code>ORD-0001</code>) automatically generated by the engine and cited across all related cash receipts and reports.</li><li><strong>Status Badge:</strong> A clear color indicator of current job state: <ul><li><code>NEW</code> — order logged, equipment received into shop custody;</li><li><code>IN_PROGRESS</code> — tool is in work with the specialist;</li><li><code>COMPLETED</code> — work finalized, QA verified, balance settled, and ticket closed (clean green badge);</li><li><code>CANCELLED</code> — terminated ticket with processed deposit refund (red badge).</li></ul></li><li><strong>Scope and Client Info:</strong> Work title (<em>&quot;Rotary hammer maintenance: gearbox inspection and brush replacement&quot;</em>) and the customer name linked from the directory.</li><li><strong>Financial Deal Balance:</strong> Total agreed order price (<code>Total Amount</code>) alongside received customer deposit (<code>Prepayment</code>).</li><li><strong>Quick Action Controls:</strong> Ticket completion button (green checkmark icon) and ticket cancellation button (red cross icon).</li></ul><hr><h2 id="prerequisites-for-registering-work-orders" tabindex="-1">Prerequisites for Registering Work Orders <a class="header-anchor" href="#prerequisites-for-registering-work-orders" aria-label="Permalink to &quot;Prerequisites for Registering Work Orders&quot;">​</a></h2><p>Before opening a service work order, ensure the following are prepared:</p><ol><li><strong>Client Profile:</strong> The customer is recorded in the <strong>Clients</strong> directory with contact information for approving discovered defects;</li><li><strong>Service Catalog &amp; Rates:</strong> Standard repair procedures, standard hours, and labor rates are set up in the <strong>Service Catalog</strong>;</li><li><strong>Spare Parts in Inventory:</strong> Common replacement components and consumables (bearings, brushes, lubricants) are received in <strong>Raw Materials</strong>.</li></ol><hr><h2 id="step-by-step-guide-registering-a-new-service-order" tabindex="-1">Step-by-Step Guide: Registering a New Service Order <a class="header-anchor" href="#step-by-step-guide-registering-a-new-service-order" aria-label="Permalink to &quot;Step-by-Step Guide: Registering a New Service Order&quot;">​</a></h2><p>Logging a ticket occurs when receiving equipment or confirming maintenance scope with the customer.</p><ol><li>Navigate to the <strong>&quot;Orders&quot;</strong> tab and click the <strong>&quot;New Service Order&quot;</strong> button in the upper-right corner.</li><li>In the modal dialog, specify order details: <ul><li><strong>&quot;Order Description&quot;:</strong> Clear and concise scope definition (<em>&quot;Diagnostics and runout correction of router chuck&quot;</em>);</li><li>Enter the customer&#39;s name in the <strong>&quot;Client&quot;</strong> field.</li><li><strong>&quot;Total Amount&quot;:</strong> Agreed gross repair cost including estimated replacement parts;</li><li><strong>&quot;Prepayment&quot;:</strong> Exact deposit amount paid upfront by the customer during check-in.</li></ul></li><li>Click the <strong>&quot;Save&quot;</strong> button.</li></ol><div class="info custom-block"><p class="custom-block-title">How the deposit is saved</p><p>If you enter a deposit such as $20.00, OmniCraft ERP saves the order and the income entry on the <strong>&quot;Cash Flow&quot;</strong> tab together. The entry includes the order number. If the cash entry fails, the form stays open and shows an error.</p></div><hr><h2 id="workshop-execution-stages-and-spare-parts" tabindex="-1">Workshop Execution: Stages and Spare Parts <a class="header-anchor" href="#workshop-execution-stages-and-spare-parts" aria-label="Permalink to &quot;Workshop Execution: Stages and Spare Parts&quot;">​</a></h2><p>Once the ticket is open, the technician initiates inspection and disassembly. The order routes through two primary accounting conduits:</p><h3 id="_1-spare-parts-and-consumables-deduction" tabindex="-1">1. Spare Parts and Consumables Deduction <a class="header-anchor" href="#_1-spare-parts-and-consumables-deduction" aria-label="Permalink to &quot;1. Spare Parts and Consumables Deduction&quot;">​</a></h3><p>All replacement components (bearings, carbon brushes, oil seals, gears) and technical lubricants are deducted from inventory balances via the <strong>&quot;Materials&quot;</strong> tab:</p><ul><li>Select required items from stock;</li><li>Input the exact consumed quantity;</li><li>Reference the active order number in the reason note.</li></ul><p>Deductions follow the Moving Average Cost (MAC) method, protecting your shop from distorted margin calculations when component batches are acquired at fluctuating vendor rates.</p><h3 id="_2-computing-actual-job-cost" tabindex="-1">2. Computing Actual Job Cost <a class="header-anchor" href="#_2-computing-actual-job-cost" aria-label="Permalink to &quot;2. Computing Actual Job Cost&quot;">​</a></h3><p>The system computes full operational cost for every individual order:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Order Cost Structure</span><div class="formula-heading">Direct and Indirect Expense Allocation</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Total Cost</span><span class="math-op">=</span><span class="math-num">Parts Cost</span><span class="math-op">+</span><span class="math-num">(Labor Hours × Hourly Rate)</span><span class="math-op">+</span><span class="math-num">Shop Overhead</span></div></div></div><div class="tip custom-block"><p class="custom-block-title">Workshop Foreman Tip: Confirming Hidden Defects Before Ordering Parts</p><p>If opening a gearbox reveals catastrophic gear wear that doubles preliminary cost estimates, pause work immediately. Confirm the revised estimate with the client via messaging and update the &quot;Total Amount&quot; field on the ticket. A workshop should never finance unanticipated custom parts out of pocket.</p></div><hr><h2 id="completing-the-order-and-final-settlement" tabindex="-1">Completing the Order and Final Settlement <a class="header-anchor" href="#completing-the-order-and-final-settlement" aria-label="Permalink to &quot;Completing the Order and Final Settlement&quot;">​</a></h2><p>Following bench assembly, recalibration, and successful testing under operational load, the equipment is released to the customer.</p><ol><li>Locate the ticket in your list and click the <strong>&quot;Complete Order&quot;</strong> button (green checkmark).</li><li>The system requests verification: <em>&quot;Complete the order and record the final payment to DDS?&quot;</em>.</li><li><strong>What Happens Under the Hood:</strong><ul><li>The software compares total order price against prior customer deposits, determining remaining balance: <code>Balance Due = Total Amount − Prepayment</code>;</li><li>The workshop cash ledger (<strong>&quot;DDS&quot;</strong> tab) records the secondary cash inflow for the remaining amount under <em>&quot;Final service payment&quot;</em>;</li><li>The ticket transitions to the permanent <code>COMPLETED</code> state with an exact closing timestamp;</li><li>Final job cost is recorded and net commercial margin flows into analytical performance reports.</li></ul></li></ol><hr><h2 id="handling-exceptions-ticket-cancellation-and-refunds" tabindex="-1">Handling Exceptions: Ticket Cancellation and Refunds <a class="header-anchor" href="#handling-exceptions-ticket-cancellation-and-refunds" aria-label="Permalink to &quot;Handling Exceptions: Ticket Cancellation and Refunds&quot;">​</a></h2><p>When inspection reveals unrepairable structural housing cracks or the client declines costly restoration:</p><ol><li>Click the <strong>&quot;Cancel Order&quot;</strong> button (red cross icon on ticket card).</li><li>Confirm the action in the prompt: <em>&quot;Are you sure you want to cancel this order? Advance payment will be refunded.&quot;</em>.</li><li><strong>Financial Impact:</strong><ul><li>If a customer advance was registered, the engine automatically logs a cash refund expense transaction in DDS under <em>&quot;Refund of advance on canceled order&quot;</em>;</li><li>The ticket moves to <code>CANCELLED</code> status, removing phantom revenue from operational accounting.</li></ul></li></ol><div class="info custom-block"><p class="custom-block-title">How settlement is recorded</p><p>If the final payment or refund fails to post, the order keeps its previous status. Completing an order again leaves a single final payment entry. A canceled order cannot be completed.</p></div><hr><h2 id="service-order-lifecycle-reference-matrix" tabindex="-1">Service Order Lifecycle Reference Matrix <a class="header-anchor" href="#service-order-lifecycle-reference-matrix" aria-label="Permalink to &quot;Service Order Lifecycle Reference Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Order Status</th><th style="text-align:left;">Available UI Actions</th><th style="text-align:left;">Cash Flow (DDS)</th><th style="text-align:left;">Warehouse Inventory Flow</th><th style="text-align:left;">Balance Sheet &amp; Capital Impact</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>NEW</strong></td><td style="text-align:left;">Edit, complete, cancel</td><td style="text-align:left;">Deposit inflow logged (if paid)</td><td style="text-align:left;">No inventory movement</td><td style="text-align:left;">Customer performance liability booked</td></tr><tr><td style="text-align:left;"><strong>IN_PROGRESS</strong></td><td style="text-align:left;">Deduct parts, cancel</td><td style="text-align:left;">No monetary entries</td><td style="text-align:left;">Parts deducted at MAC cost</td><td style="text-align:left;">Work-in-progress cost accumulates</td></tr><tr><td style="text-align:left;"><strong>COMPLETED</strong></td><td style="text-align:left;">View history &amp; receipt</td><td style="text-align:left;">Final payment inflow logged</td><td style="text-align:left;">Deductions finalized</td><td style="text-align:left;">Net profit locked, equity expands</td></tr><tr><td style="text-align:left;"><strong>CANCELLED</strong></td><td style="text-align:left;">Review cancel reason</td><td style="text-align:left;">Refund expense logged</td><td style="text-align:left;">Unused components restocked</td><td style="text-align:left;">Liabilities cleared, liquidity returned</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Master Craftsman Advice: The 50% Rule for Custom-Ordered Assemblies</p><p>If completing an order requires purchasing specialized bearings or electronics from external suppliers, never accept symbolic token deposits. The customer advance must cover at least 100% of vendor procurement costs and freight. If the customer abandons the equipment, your workshop remains financially protected.</p></div>',40))])}const k=a(d,[["render",p]]);export{b as __pageData,k as default};
